describe('File Upload - Unsupported File Type Error', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display error message when uploading unsupported file type', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 400,
      body: {
        error: 'Unsupported file type',
        message: 'Only PDF, DOCX, and JPG files are allowed.'
      }
    }).as('uploadError');

    // Attempt to upload an unsupported file type (e.g., .txt)
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/unsupported-file.txt', { force: true });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Unsupported file type');

    // Verify error summary is visible
    cy.get('[data-testid="error-summary"]').should('be.visible');
    cy.get('[data-testid="error-summary"]').should('contain', 'File type');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Verify file input is cleared
    cy.get('[data-testid="file-input"]').should('have.value', '');

    // Verify upload button is disabled
    cy.get('[data-testid="upload-button"]').should('be.disabled');
  });

  it('should handle multiple unsupported file types in a row', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 400,
      body: {
        error: 'Unsupported file type',
        message: 'Only PDF, DOCX, and JPG files are allowed.'
      }
    }).as('uploadError');

    // Attempt to upload multiple unsupported file types
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/unsupported-file.txt', { force: true });
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/unsupported-file.docx', { force: true });
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/unsupported-file.jpg', { force: true });

    // Verify error message is displayed for each file
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Unsupported file type');

    // Verify error summary is updated with multiple errors
    cy.get('[data-testid="error-summary"]').should('be.visible');
    cy.get('[data-testid="error-summary"]').should('contain', 'File type');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Verify file input is cleared
    cy.get('[data-testid="file-input"]').should('have.value', '');

    // Verify upload button is disabled
    cy.get('[data-testid="upload-button"]').should('be.disabled');
  });
});
